+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+const formStatus = document.getElementById('formStatus');
+
+const phoneRegex = /^(\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/;
+
+function validateEmail(email) {
+  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+  return emailRegex.test(email);
+}
+
+function validatePhone(phone) {
+  if (phone.trim() === '') return true;
+  return phoneRegex.test(phone);
+}
+
+function clearFieldError(field, errorElement) {
+  field.setAttribute('aria-invalid', 'false');
+  errorElement.textContent = '';
+  errorElement.classList.remove('show');
+}
+
+function setFieldError(field, errorElement, message) {
+  field.setAttribute('aria-invalid', 'true');
+  errorElement.textContent = `Error: ${message}`;
+  errorElement.classList.add('show');
+}
+
+function validateField(field, errorElement) {
+  const value = field.value.trim();
+  const fieldName = field.id;
+
+  if (fieldName === 'fullName') {
+    if (value === '') {
+      setFieldError(field, errorElement, 'Please enter your full name.');
+      return false;
+    }
+    if (value.length < 2) {
+      setFieldError(field, errorElement, 'Full name must be at least 2 characters.');
+      return false;
+    }
+    clearFieldError(field, errorElement);
+    return true;
+  }
+
+  if (fieldName === 'email') {
+    if (value === '') {
+      setFieldError(field, errorElement, 'Please enter your email address.');
+      return false;
+    }
+    if (!validateEmail(value)) {
+      setFieldError(field, errorElement, 'Please enter a valid email like name@example.com.');
+      return false;
+    }
+    clearFieldError(field, errorElement);
+    return true;
+  }
+
+  if (fieldName === 'phone') {
+    if (!validatePhone(value)) {
+      setFieldError(field, errorElement, 'Please enter a valid phone number like (123) 456-7890.');
+      return false;
+    }
+    clearFieldError(field, errorElement);
+    return true;
+  }
+
+  return true;
+}
+
+fullNameInput.addEventListener('blur', () => {
+  validateField(fullNameInput, document.getElementById('fullName-error'));
+});
+
+emailInput.addEventListener('blur', () => {
+  validateField(emailInput, document.getElementById('email-error'));
+});
+
+phoneInput.addEventListener('blur', () => {
+  validateField(phoneInput, document.getElementById('phone-error'));
+});
+
+fullNameInput.addEventListener('input', () => {
+  if (fullNameInput.getAttribute('aria-invalid') === 'true') {
+    validateField(fullNameInput, document.getElementById('fullName-error'));
+  }
+});
+
+emailInput.addEventListener('input', () => {
+  if (emailInput.getAttribute('aria-invalid') === 'true') {
+    validateField(emailInput, document.getElementById('email-error'));
+  }
+});
+
+phoneInput.addEventListener('input', () => {
+  if (phoneInput.getAttribute('aria-invalid') === 'true') {
+    validateField(phoneInput, document.getElementById('phone-error'));
+  }
+});
+
+form.addEventListener('submit', (e) => {
+  e.preventDefault();
+  formStatus.textContent = '';
+  formStatus.classList.remove('success', 'error');
+
+  const fullNameValid = validateField(fullNameInput, document.getElementById('fullName-error'));
+  const emailValid = validateField(emailInput, document.getElementById('email-error'));
+  const phoneValid = validateField(phoneInput, document.getElementById('phone-error'));
+
+  if (!fullNameValid || !emailValid || !phoneValid) {
+    const firstInvalidField = !fullNameValid 
+      ? fullNameInput 
+      : !emailValid 
+      ? emailInput 
+      : phoneInput;
+    
+    firstInvalidField.focus();
+    formStatus.textContent = 'Please fix the errors above.';
+    formStatus.classList.add('error');
+    return;
+  }
+
+  formStatus.textContent = 'Thank you! Your message has been sent successfully. We\'ll get back to you soon.';
+  formStatus.classList.add('success');
+  form.reset();
+  
+  setTimeout(() => {
+    formStatus.textContent = '';
+    formStatus.classList.remove('success');
+  }, 5000);
+});
+
