AssistantMessageToolRequest(name='bash', tool_call_id='tooluse_U63rZIaETwLKF2qzOe4Dt5', arguments={'command': "cd /workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-dark--validation-message-present/claude-haiku-4.5__s3 && node << 'TESTEOF'
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlContent = fs.readFileSync(path.join(__dirname, 'index.html'), 'utf8');
  await page.setContent(htmlContent, { waitUntil: 'load' });

  const axeSource = require('axe-core').source;
  await page.evaluate(axeSource);

  const results = await page.evaluate(() => window.axe.run());

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})();
TESTEOF
