const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({ headless: true, timeout: 10000 });
  const context = await browser.newContext();
  const page = await context.newPage();
  page.setDefaultTimeout(5000);

  const htmlContent = fs.readFileSync('./index.html', 'utf8');
  await page.setContent(htmlContent);

  const axeSource = require('axe-core').source;
  await page.evaluate(axeSource);

  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bpViolations = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log('ACCESSIBILITY TEST RESULTS:');
  console.log(`WCAG Violations: ${wcagViolations.length}`);
  console.log(`Best Practice Violations: ${bpViolations.length}`);
  console.log(`Passes: ${results.passes.length}`);

  if (wcagViolations.length === 0 && bpViolations.length === 0) {
    console.log('\n✓ PASS - No accessibility violations found!');
  }

  await browser.close();
  process.exit(wcagViolations.length > 0 ? 1 : 0);
})();
TESTEOF
